query:
SELECT DISTINCT ?word ?item ?itemLabel ?propLabel ?obj ?objLabel ?rank ?stmt ?ps WHERE {
  VALUES ?word { "angle"@en "arc"@en "artery"@en "axis"@en "axle"@en "bark"@en "bearing"@en "belt"@en "blizzard"@en "blossom"@en "bone"@en "brain"@en "branch"@en "breeze"@en "bud"@en "cam"@en "cartilage"@en "ceremony"@en "charter"@en "chill"@en "chord"@en "circle"@en "circuit"@en "climate"@en "cloud"@en "clutch"@en "coil"@en "cone"@en "contract"@en "council"@en "cube"@en "curve"@en "custom"@en "dew"@en "diameter"@en "diaphragm"@en "drizzle"@en "election"@en "ellipse"@en "esophagus"@en "fern"@en "foliage"@en "frost"@en "fruit"@en "fuse"@en "gale"@en "game"@en "gasket"@en "gear"@en "gland"@en "glow"@en "grain"@en "guild"@en "habit"@en "hail"@en "heart"@en "herb"@en "joint"@en "kidney"@en "lattice"@en "law"@en "leader"@en "leaf"@en "lever"@en "ligament"@en "line"@en "liver"@en "lung"@en "market"@en "marrow"@en "mist"@en "monsoon"@en "moss"@en "motor"@en "muscle"@en "nerve"@en "norm"@en "overcast"@en "palm"@en "petal"@en "piston"@en "pivot"@en "plane"@en "plasma"@en "point"@en "pollen"@en "polygon"@en "prism"@en "pulley"@en "quadrant"@en "radius"@en "rainbow"@en "rank"@en "reflex"@en "reward"@en "ritual"@en "role"@en "root"@en "rotor"@en "rumor"@en "sapling"@en "seed"@en "seedling"@en "segment"@en "shaft"@en "shower"@en "shrub"@en "signal"@en "skin"@en "sleet"@en "slope"@en "society"@en "sphere"@en "spring"@en "sprocket"@en "squall"@en "square"@en "stem"@en "storm"@en "sunset"@en "switch"@en "tangent"@en "team"@en "tempest"@en "tendon"@en "thaw"@en "thorn"@en "thunder"@en "tissue"@en "tradition"@en "treaty"@en "tree"@en "triangle"@en "trunk"@en "typhoon"@en "valley"@en "valve"@en "vein"@en "vertex"@en "vessel"@en "vine"@en "vote"@en "wheel"@en "widget"@en }
  ?item rdfs:label ?word .
  VALUES ?p { p:P1542 p:P155 p:P156 p:P361 p:P461 p:P527 p:P828 }
  ?item ?p ?stmt .
  ?stmt ?ps ?obj .
  FILTER(STRSTARTS(STR(?ps), "http://www.wikidata.org/prop/statement/"))
  FILTER(isIRI(?obj))
  OPTIONAL { ?stmt wikibase:rank ?rank . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 10000
